item:
except Exception:
    rank = int(os.environ.get('PMI_RANK') or os.environ.get('OMPI_COMM_WORLD_RANK') or '0')
    size = int(os.environ.get('PMI_SIZE') or os.environ.get('OMPI_COMM_WORLD_SIZE') or '1')
    return (rank, size)

except Exception as e:
    print(f'分析过程中出现错误: {e}')
    raise SystemExit(1)

except Exception as e:
    print(f'加载能带数据失败: {e}')
    raise RuntimeError(f'加载能带数据失败: {e}') from e

except Exception as e:
    print(f'加载特征向量数据失败: {e}')
    raise RuntimeError(f'加载特征向量数据失败: {e}') from e

except Exception as e:
    print(f'保存结果时发生错误: {e}', file=sys.stderr)
    raise RuntimeError(f'保存结果失败: {e}') from e

except Exception as e:
    print(f'分析谷 {valley} 时出错: {e}')
    failures.append(f'{valley}: {e}')

except BaseException:
    for source, dest in linked:
        if dest.exists() and source.samefile(dest):
            dest.unlink()
    for directory in reversed(directories):
        try:
            directory.rmdir()
        except OSError:
            pass
    raise

except Exception as e:
    msg = str(e)
    if 'error code 95' in msg or 'inner product is not well defined' in msg:
        raise RuntimeError('SLEPc failed with an inner-product error (often caused by S(k) not being strictly Hermitian/HPD). Try setting compute.slepc_make_hermitian: true (default) and/or a small compute.slepc_spd_shift (e.g. 1e-10). If it still fails, your overlap matrix may not satisfy GHEP assumptions.') from e
    raise

except Exception as e:
    calc._set_progress_stage(i, 'error')
    return (i, False, str(e), None)

except Exception as e:
    print(f'错误: {e}')
    return 1

except Exception as exc:
    try:
        self._store._atomic_write_artifact(self._pending)
    except Exception:
        pass
    raise SelectionTransactionError(SelectionFailureCode.PERSISTENCE_FAILURE, 'final selection marker failed persistence validation') from exc

except Exception as exc:
    exc.add_note(f'kp model response-basis compilation failed during finite-p symbolic-atom compilation for group {group_index} ({len(finite_seeds)} seeds)')
    raise

except Exception as exc:
    exc.add_note(f'kp model response-basis compilation failed during p=0 fixed-space compilation for group {group_index} ({len(zero_fixed_seeds)} seeds)')
    raise

except Exception as exc:
    exc.add_note(f'kp model response-basis compilation failed during complete p=0 graded projection for group {group_index} ({len(zero_complete_seeds)} seeds)')
    raise

except Exception as exc:
    exc.add_note(f'kp model response-basis compilation failed during declared p=0 orbit-representative projection for group {group_index} ({len(zero_orbit_seeds)} seeds)')
    raise

except Exception as exc:
    exc.add_note(f'kp model response-basis compilation failed during certified sparse group actions for group {group_index} ({len(seeds)} seeds)')
    raise
